import { supabase } from '@/integrations/supabase/client';
import { defaultOperations, validateOperations, type CompanyOperations, type OperationMetrics, reportMetrics } from './companyOperations';
import { isSettingsConflict } from './settingsConflict';
export type OperationsEnvelope={settings:CompanyOperations;version:number};
// New RPCs use a narrow adapter until generated Supabase types are regenerated by the root.
interface OperationsClient { rpc(name:string,args:Record<string,unknown>):PromiseLike<{data:unknown;error:{code?:string}|null}> }
const client=supabase as unknown as OperationsClient;
export async function fetchCompanyOperations(companyId:string):Promise<OperationsEnvelope>{
 if(!companyId)throw new Error('Empresa obrigatória.');
 const {data,error}=await client.rpc('get_company_operations',{_company_id:companyId});
 if(error)throw new Error('Operação indisponível. Confira acesso e migração local.');
 const envelope=data as {settings:unknown;version:number}|null;
 if(!envelope||!Number.isSafeInteger(envelope.version)||envelope.version<0)throw new Error('Resposta operacional inválida.');
 return {settings:envelope.version===0 && envelope.settings===null?defaultOperations():validateOperations(envelope.settings),version:envelope.version};
}
export async function saveCompanyOperations(companyId:string,settings:CompanyOperations,version:number):Promise<OperationsEnvelope>{
 if(!companyId||!Number.isSafeInteger(version)||version<0)throw new Error('Empresa ou versão inválida.');
 const {data,error}=await client.rpc('save_company_operations',{_company_id:companyId,_settings:validateOperations(settings),_expected_version:version});
 if(error)throw new Error(isSettingsConflict(error)?'Outra pessoa alterou a operação. Recarregue antes de salvar.':'Não foi possível salvar a operação.');
 const result=data as OperationsEnvelope;
 if(!result||result.version!==version+1)throw new Error('Versão operacional inesperada.');
 return {settings:validateOperations(result.settings),version:result.version};
}
export async function fetchOperationMetrics(companyId:string):Promise<OperationMetrics>{
 if(!companyId)throw new Error('Empresa obrigatória.');
 const {data,error}=await client.rpc('get_company_operation_metrics',{_company_id:companyId});
 if(error||!data||typeof data!=='object')throw new Error('Indicadores indisponíveis.');
 const value=data as OperationMetrics;
 if(reportMetrics.some(k=>!Number.isSafeInteger(value[k])||value[k]<0))throw new Error('Indicadores inválidos.');
 return value;
}

/** Call before any side effect; a stale UI policy must not initiate a disabled action. */
export async function assertCompanyOperationalTransition(companyId:string,source:string,target:string):Promise<void>{
 if(!companyId)throw new Error('Empresa obrigatória.');
 const {data,error}=await client.rpc('assert_company_operation_transition',{_company_id:companyId,_source:source,_target:target});
 if(error||data!==true)throw new Error('Transição indisponível. Recarregue e confira a política da empresa.');
}
